import {DurableObject} from "cloudflare:workers";
interface Env {
 QUEUE:Fetcher;SCHEDULER:Fetcher;BOOT_ID:string;
 BOOT_STATE:DurableObjectNamespace<BootAdmission>;
}
/** Private component warm-up only. This is not application acceptance. A fresh
 * unpredictable boot ID is generated by the actual process owner every spawn.
 * The public gateway stays closed until this boot's real durable services reply. */
export class BootAdmission extends DurableObject<Env> {
 async fetch(request:Request){
  if(!/^[a-f0-9]{64}$/.test(this.env.BOOT_ID))throw Error("actual_boot_identity_required");
  const path=new URL(request.url).pathname;
  if(request.method==="POST" && path==="/initialize"){
   const queue=await this.env.QUEUE.fetch("http://private/metrics");
   if(queue.status!==200)throw Error("actual_queue_initialization_failed");
   const q=await queue.json<Record<string,number>>();
   if(!["backlogCount","backlogBytes","deadCount","retainedBytes"].every(k=>Number.isSafeInteger(q[k]) && q[k]!>=0))
    throw Error("actual_queue_readback_invalid");
   const scheduled=await this.env.SCHEDULER.fetch("http://private/status");
   if(scheduled.status!==200)throw Error("actual_scheduler_initialization_failed");
   const s=await scheduled.json<{tick:string;scheduledAt:number;nextAt:number;attempts:number;inFlight:boolean}>();
   if(typeof s.tick!=="string" || !Number.isSafeInteger(s.nextAt) || !Number.isSafeInteger(s.scheduledAt) ||
     !Number.isSafeInteger(s.attempts) || typeof s.inFlight!=="boolean")throw Error("actual_scheduler_readback_invalid");
   const value={initialized:true,bootId:this.env.BOOT_ID,queue:q,scheduler:s};
   await this.ctx.storage.put("actual-component-initialization",value);await this.ctx.storage.sync();
   return Response.json(await this.ctx.storage.get("actual-component-initialization"));
  }
  if(request.method==="GET" && path==="/ready"){
   const current=await this.ctx.storage.get<{bootId:string}>("actual-component-initialization");
   return current?.bootId===this.env.BOOT_ID?Response.json(current):new Response(null,{status:503});
  }
  return new Response(null,{status:404});
 }
}
export default {fetch(request:Request,env:Env){
 return env.BOOT_STATE.get(env.BOOT_STATE.idFromName(env.BOOT_ID)).fetch(request);
}};
